import subprocess, sys, os
BIN="/home/user/Deepresearch.se/pygram/build/pygram"
ENV=dict(os.environ); ENV["PYGRAM_CAPTURE"]="0"
def run(cmd, src):
    p=subprocess.run(cmd+["-c",src],capture_output=True,text=True,env=ENV,timeout=20)
    return p.returncode,p.stdout,p.stderr
def classify(src):
    rc,so,se=run(["python3"],src)
    prc,pso,pse=run([BIN],src)
    if prc==90 and pse.startswith("pygram: unsupported: ") and pse.count("\n")==1 and pso=="":
        return "UNSUPPORTED",(rc,so),(prc,pso,pse)
    if prc==90:
        return "BAD90",(rc,so),(prc,pso,pse)
    if (rc==0)!=(prc==0):
        return "MISMATCH",(rc,so),(prc,pso,pse)
    if rc!=0 and prc!=0:
        return "MATCH-ERR",(rc,so),(prc,pso,pse)
    if so!=pso:
        return "MISMATCH",(rc,so),(prc,pso,pse)
    return "MATCH",(rc,so),(prc,pso,pse)
if __name__=="__main__":
    for src in sys.argv[1:]:
        v,a,b=classify(src)
        print(v,"|",repr(src),"| cpy",a,"| pyg",b)

